#include <stdio.h>
#include <stdint.h>

int main(void) {
    uint8_t a = 200;
    uint8_t b = 100;
    uint8_t c = a + b;
    printf("%d\n", c);
    return 0;
}

#include <stdio.h>
#include <stdint.h>

int main(void) {
    uint8_t x = 3;
    x = x - 5;
    printf("%d\n", x);
    return 0;
}

#include <stdio.h>

int main(void) {
    float f = 0.1f;
    double d = 0.1;
    printf("%d\n", f == d);
    return 0;
}

#include <stdio.h>
#include <stdint.h>

int main(void) {
    uint16_t v = 0x0102;
    unsigned char *p = (unsigned char *)&v;
    printf("%d %d\n", p[0], p[1]);
    return 0;
}

#include <stdio.h>

int main(void) {
    int arr[] = {10, 20, 30, 40};
    unsigned n = 4;
    for (unsigned i = n - 1; i >= 0; i--)
        printf("%d\n", arr[i]);
    return 0;
}

#include <stdio.h>
#include <stdint.h>

int main(void) {
    int8_t s = -3;
    int32_t w = s;
    unsigned char *p = (unsigned char *)&w;
    printf("%02X %02X\n", p[0], p[3]);
    return 0;
}

#include <stdio.h>

int main(void) {
    double total = 0.0;
    for (int i = 0; i < 10; i++)
        total += 0.1;
    if (total == 1.0)
        printf("done\n");
    else
        printf("not done\n");
    return 0;
}

#include <stdio.h>
#include <stdint.h>

int main(void) {
    uint32_t x = 0x00434241;
    printf("%s\n", (char *)&x);
    return 0;
}

#include <stdio.h>

int main(void) {
    char b = (char)0xC8;  // byte read from a file
    int value = b;
    printf("%d\n", value); // expected 200
    return 0;
}
